const cfg = $('Set - Config').first().json;
const result = $input.first().json;
const customers = result.data || [];
const customer = customers[0] || null;

return [{
  json: {
    ...cfg,
    customerFound: !!customer,
    customerId: customer?.id || null,
    customerEmail: customer?.email || null,
    customerMetadata: customer?.metadata || {}
  }
}];

const ctx = $('JS - Resolve Customer').first().json;
const result = $input.first().json;
const subs = result.data || [];
const subscription = subs[0] || null;
const item = subscription?.items?.data?.[0] || null;

return [{
  json: {
    ...ctx,
    subscriptionActive: !!subscription,
    subscriptionId: subscription?.id || null,
    subscriptionPriceId: item?.price?.id || ctx.stripeUsagePriceIdFallback,
    subscriptionItemId: item?.id || null
  }
}];

const ctx = $('JS - Parse Subscription').first().json;
const usageResult = $input.first().json;
const summaries = usageResult.data || [];
const currentUsage = summaries[0]?.total_usage || 0;

const limit = ctx.planLimits?.[ctx.subscriptionPriceId] ?? 100;
const withinLimit = currentUsage < limit;
const allowed = ctx.subscriptionActive === true && withinLimit;

let reason = 'ok';
if (!ctx.subscriptionActive) reason = 'no_active_subscription';
else if (!withinLimit) reason = 'usage_limit_exceeded';

return [{
  json: {
    ...ctx,
    currentUsage,
    usageLimit: limit,
    entitlementAllowed: allowed,
    entitlementReason: reason
  }
}];

const ctx = $('JS - Check Entitlement').first().json;
const response = $input.first().json;
const textBlock = (response.content || []).find(b => b.type === 'text');

return [{
  json: {
    ...ctx,
    generatedContentType: 'text',
    generatedContent: textBlock?.text || '',
    generationError: !textBlock
  }
}];

const ctx = $('JS - Check Entitlement').first().json;
const response = $input.first().json;

return [{
  json: {
    ...ctx,
    generatedContentType: 'image',
    generatedContent: response.url || response.imageUrl || response.data?.[0]?.url || '',
    generationError: !(response.url || response.imageUrl || response.data?.[0]?.url)
  }
}];

const ctx = $('Merge - Combine Generation Results').first().json;

return [{
  json: {
    success: true,
    contentType: ctx.generatedContentType,
    content: ctx.generatedContent,
    usage: {
      current: ctx.currentUsage + 1,
      limit: ctx.usageLimit
    }
  }
}];
